def get_large_corpus(min_tokens: int = 4096, tokenizer=None) -> str:
    """
    Returns non-repeating natural text by joining unique paragraphs.
    """
    text = "\n\n".join(CORPUS_PARAGRAPHS)
    if tokenizer is not None:
        tokens = tokenizer(text, return_tensors="pt").input_ids
        cur_len = tokens.shape[1]
        if cur_len < min_tokens:
            raise ValueError(
                f"Requested {min_tokens} tokens, but corpus only contains {cur_len} non-repeating tokens. "
                "Add more distinct paragraphs to benchmarks/corpus.py rather than looping."
            )
    return text
